{"function":"() => {
const out=[];
const sel=['.br-skiplink a','.marca-govbr','.marca-govbr span','.marca-govbr strong','.crumb a','.crumb span[aria-current]','h1','.apoio-solicitacao','label[for=nome]','#nome','#cpf','#cpf-apoio','label[for=servico]','#servico','legend','label[for=forma-video]','#data-preferencial','#data-apoio','#descricao','#descricao-apoio','.upload-label','.upload-button','.upload-button span','#documentos','#documentos-apoio','label[for=declaracao]','.acao-cancelar','.acao-enviar','h2','.table-title','th','td','.page','.page.active','.br-pagination button','.input-icon i','.retorno-envio','.br-radio input','.br-checkbox input'];
for(const s of sel){const e=document.querySelector(s); if(!e){out.push(s+': none');continue;} const c=getComputedStyle(e); const r=e.getBoundingClientRect(); out.push(`${s}: color ${c.color} bg ${c.backgroundColor} fs ${c.fontSize} fw ${c.fontWeight} disp ${c.display} vis ${c.visibility} op ${c.opacity} rect ${Math.round(r.x)},${Math.round(r.y)},${Math.round(r.width)}x${Math.round(r.height)} border ${c.borderTopColor} ${c.borderTopWidth} ${c.borderTopStyle}`);}
return out.join('\n');}"}

{"function":"() => {
const r=[];
for(const s of ['#cpf','#servico','#data-preferencial']){const c=getComputedStyle(document.querySelector(s),'::placeholder'); r.push(s+' placeholder '+c.color+' '+c.fontStyle+' '+c.opacity);}
document.querySelectorAll('.page').forEach(p=>{const c=getComputedStyle(p); r.push('page '+p.textContent+' '+c.color+' / '+c.backgroundColor+' cur:'+p.getAttribute('aria-current'));});
const td=document.querySelector('tbody tr'); r.push('tr bg '+getComputedStyle(td).backgroundColor);
const sec=document.querySelector('.historico'); let e=sec; while(e){const b=getComputedStyle(e).backgroundColor; if(b!=='rgba(0, 0, 0, 0)'){r.push('hist bg '+b+' '+e.className);break;} e=e.parentElement;}
const f=document.querySelector('form'); r.push('form bg '+getComputedStyle(f).backgroundColor);
r.push('body bg '+getComputedStyle(document.body).backgroundColor);
const tbl=document.querySelector('.br-table'); r.push('br-table bg '+getComputedStyle(tbl).backgroundColor);
document.querySelectorAll('.br-radio label, .br-checkbox label').forEach(l=>{const b=getComputedStyle(l,'::before'); r.push(l.textContent+' before border '+b.borderColor+' '+b.borderWidth+' w'+b.width);});
return r.join('\n');}"}

